void build_gc_manager ( struct f2fs_sb_info * sbi ) { u64 main_count , resv_count , ovp_count ; DIRTY_I ( sbi ) -> v_ops = & default_v_ops ; main_count = SM_I ( sbi ) -> main_segments << sbi -> log_blocks_per_seg ; resv_count = SM_I ( sbi ) -> reserved_segments << sbi -> log_blocks_per_seg ; ovp_count = SM_I ( sbi ) -> ovp_segments << sbi -> log_blocks_per_seg ; if ( sbi -> s_ndevs && sbi -> segs_per_sec == 1 ) { SIT_I ( sbi ) -> last_victim [ ALLOC_NEXT ] = GET_SEGNO ( sbi , FDEV ( 0 ) . end_blk ) + 1 ; } } 